package dev.kuan.kuanperion.automation.supercraft;
import dev.kuan.kuanperion.automation.*;import java.util.*;
/** Synthetic fixtures following the historical2024 official screenshot grammar, not a live2026 server claim. */
public final class SupercraftPreviewTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static final Map<String,String> IDS=Map.of("Wheat","WHEAT","Enchanted Wheat","ENCHANTED_WHEAT");
 static List<String> lore(){return List.of("✔ 320/320 (2x) Wheat","320x from Inventory","","Crafting 2 items into your inventory!","","Right-Click to set amount!","Click to craft!");}
 static ItemSnapshot button(String name,List<String> lore){return new ItemSnapshot("SCANNER_NOT_OUTPUT","minecraft:stone_pickaxe","",name,name+lore,1,lore,true);}
 static ItemSnapshot result(){return new ItemSnapshot("ENCHANTED_WHEAT","minecraft:wheat","","Enchanted Wheat","enchanted",1,List.of(),false);}
 static MenuSnapshot menu(String role,List<String> lore){var inv=SupercraftPlanTest.inventory();var slots=new ArrayList<MenuSnapshot.Slot>();for(int i=0;i<54;i++)slots.add(new MenuSnapshot.Slot(i,i==32?button(role,lore):i==24?result():SupercraftPlanTest.AIR,false));for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(54+i,inv.get(i<27?i+9:i-27),true));return new MenuSnapshot(1,7,2,"Enchanted Wheat Recipe",54,slots);}
 static SupercraftPlan.Plan plan(){return SupercraftPlan.select(SupercraftPlanTest.RECIPE,2,SupercraftPlanTest.RULES,SupercraftPlanTest.inventory()).orElseThrow();}
 static Optional<SupercraftPreview> read(MenuSnapshot menu){return SupercraftPreview.inspect(plan(),menu,IDS);}
 public static void main(String[]args){
  var m=menu("Supercraft (2x crafts)",lore());var p=read(m).orElseThrow();check(p.acceptSlot()==32&&p.resultSlot()==24&&p.ticket().click()==MenuContract.Click.PICKUP&&p.ticket().observed().equals(m),"exact role and raw output ID/catalog binding, no shift maximize or scanner-ID assumption");
  var moved=new ArrayList<>(m.slots());moved.set(10,new MenuSnapshot.Slot(10,m.item(32),false));moved.set(32,new MenuSnapshot.Slot(32,SupercraftPlanTest.AIR,false));check(read(new MenuSnapshot(1,8,3,m.title(),54,moved)).orElseThrow().acceptSlot()==10,"semantic role may move; never assume old slot32/10");
  for(String text:List.of("320x from Sacks","320x from Ender Chests","320x from Backpacks","319x from Inventory","320x from inventory")){var l=new ArrayList<>(lore());l.set(1,text);check(read(menu("Supercraft (2x crafts)",l)).isEmpty(),"inventory-only proof cannot authorize hidden or ambiguous storage consumption: "+text);}
  for(String text:List.of("✔ 319/320 Wheat","✖ 320/320 Wheat","✔ 320/319 Wheat","✔ 320/320 Carrot","✔ 320/320 (0x) Wheat","✔ 03,20/320 Wheat")){var l=new ArrayList<>(lore());l.set(0,text);check(read(menu("Supercraft (2x crafts)",l)).isEmpty(),"malformed/missing/unknown/wrong quantity materials denied: "+text);}
  for(String text:List.of("Crafting 3 items into your inventory!","Crafting 2 items into your sacks!","Crafting 2 item into your inventory!","Cost: 100 Coins")){var l=new ArrayList<>(lore());l.set(3,text);check(read(menu("Supercraft (2x crafts)",l)).isEmpty(),"wrong output target/amount/unknown cost denied");}
  for(String name:List.of("Supercraft","Supercraft (3x crafts)","Supercraft (0x crafts)","Supercraft (2x Crafts)","My Supercraft (2x crafts)"))check(read(menu(name,lore())).isEmpty(),"no fuzzy/incorrect selected craft count");
  var hidden=new ArrayList<>(lore());hidden.remove(1);check(read(menu("Supercraft (2x crafts)",hidden)).isEmpty(),"basic mode lacking source allocation is not sufficient authority");var unknown=new ArrayList<>(lore());unknown.add(1,"Cost: 1,000 Coins");check(read(menu("Supercraft (2x crafts)",unknown)).isEmpty(),"unrecognized price/extra lines are not discarded");
  var dup=new ArrayList<>(m.slots());dup.set(10,new MenuSnapshot.Slot(10,m.item(32),false));check(read(new MenuSnapshot(1,7,2,m.title(),54,dup)).isEmpty(),"duplicate roles deny whole preview");dup=new ArrayList<>(m.slots());dup.set(10,new MenuSnapshot.Slot(10,m.item(24),false));check(read(new MenuSnapshot(1,7,2,m.title(),54,dup)).isEmpty(),"duplicate output IDs never first/nearest match");
  check(read(new MenuSnapshot(1,7,2,"My Enchanted Wheat Recipe",54,m.slots())).isEmpty(),"exact recipe title");check(SupercraftPreview.inspect(plan(),m,Map.of()).isEmpty(),"no name-only guess without official IDs");
  var badPlayer=new ArrayList<>(m.slots());badPlayer.set(54,new MenuSnapshot.Slot(54,SupercraftPlanTest.AIR,true));check(read(new MenuSnapshot(1,7,3,m.title(),54,badPlayer)).isEmpty(),"menu player items must equal full protected plan baseline");
  var partial=new ArrayList<>(m.slots());partial.remove(0);check(read(new MenuSnapshot(1,7,2,m.title(),54,partial)).isEmpty(),"incomplete container observation is not complete preview");
  var one=SupercraftPlan.select(SupercraftPlanTest.RECIPE,1,SupercraftPlanTest.RULES,SupercraftPlanTest.inventory()).orElseThrow();var single=menu("Supercraft",List.of("✓ 320/160 Wheat","160x from Inventory","Crafting 1 item into your inventory!","Right-Click to set amount!","Click to craft!"));check(SupercraftPreview.inspect(one,single,IDS).isPresent(),"documented unnumbered one-craft role and exact singular output");
  var alias=new HashMap<>(IDS);alias.put("Alias Wheat","WHEAT");var repeated=new ArrayList<>(lore());repeated.add(2,"✔ 320/320 Alias Wheat");repeated.add(3,"320x from Inventory");check(SupercraftPreview.inspect(plan(),menu("Supercraft (2x crafts)",repeated),alias).isEmpty(),"two material aliases cannot create duplicate consumption rows");
  var wrongId=new ArrayList<>(m.slots());wrongId.set(24,new MenuSnapshot.Slot(24,new ItemSnapshot("OTHER","minecraft:wheat","","Enchanted Wheat","other",1,List.of(),false),false));check(read(new MenuSnapshot(1,7,2,m.title(),54,wrongId)).isEmpty(),"display name alone cannot identify recipe output");
  var extraCost=new ArrayList<>(lore());extraCost.add("Cost: 1 Coin");check(read(menu("Supercraft (2x crafts)",extraCost)).isEmpty(),"post-confirmation cost text is never ignored");
  var oversized=new ArrayList<>(lore());oversized.set(0,"✔ "+"9".repeat(300)+"/320 Wheat");check(read(menu("Supercraft (2x crafts)",oversized)).isEmpty(),"bounded numeric overflow cannot become available materials");
  System.out.println("SupercraftPreviewTest: PASS (historical strict advanced grammar, exact selected batches/input IDs/source/output destination, complete snapshot, semantic relocated button, no storage/fuzzy/maximize/unknown-cost inference)");
 }
}
